using System;
using System.Collections.Concurrent;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using Ged.Core.Compiler;
using Ged.Core.Editor;
using Ged.Core.Spatial;
using Ged.Core.Tests.Scripting;

namespace Ged.Core.Tests.Spatial;

/// <summary>
/// Synthetic-truth levels for the spatial measurements (DESIGN-QUALITY-SPEC §(g) Q1 gate), generated by Glacier's own
/// design kit and given a SEALED Shared BSP build: each has a known answer (a loop, a chokepoint, a pocket, a bridge,
/// cover, an open-air platform field, a payload chain). Built once per test run.
/// </summary>
internal static class SpatialFixtures
{
    private static readonly ConcurrentDictionary<string, (EditorDocument Doc, SpatialLevel Level)> Built = new(StringComparer.Ordinal);

    /// <summary>Spawns (and a few items) on a room's floor, so it is playable.</summary>
    private static string Populate(string room, int spawns, double yaw = 0) =>
        $"for i = 1, {spawns} do local x = {room}.min.x + ({room}.max.x - {room}.min.x) * (i / ({spawns} + 1)) " +
        $"level.place{{kind = 'respawn', pos = {{x, {room}.floor_y, {room}.center.z}}, yaw = {yaw.ToString(CultureInfo.InvariantCulture)}}} end\n";

    /// <summary>Four 16 m rooms in a ring joined by four corridors around a solid core: one loop at the 8 m scale, no chokepoint.</summary>
    public const string Loop = """
        local a = kit.room{name = 'a', pos = {0, 0, 0}, size = {16, 6, 16}}
        local b = kit.room{name = 'b', pos = {32, 0, 0}, size = {16, 6, 16}}
        local c = kit.room{name = 'c', pos = {32, 0, 32}, size = {16, 6, 16}}
        local d = kit.room{name = 'd', pos = {0, 0, 32}, size = {16, 6, 16}}
        kit.corridor{a = a, b = b, width = 5}
        kit.corridor{a = b, b = c, width = 5}
        kit.corridor{a = c, b = d, width = 5}
        kit.corridor{a = d, b = a, width = 5}
        """;

    /// <summary>
    /// Two 24 m rooms joined by one long corridor: its cells cut the level in half (chokepoints), no loop. The corridor
    /// runs inside one row of 8 m cells (offset 4) — one straddling a cell boundary is two cells wide and has no single cut cell.
    /// </summary>
    public const string Choke = """
        local a = kit.room{name = 'a', pos = {0, 0, 0}, size = {24, 6, 24}}
        local b = kit.room{name = 'b', pos = {60, 0, 0}, size = {24, 6, 24}}
        kit.corridor{a = a, b = b, width = 4.5, offset = 4}
        """;

    /// <summary>The loop plus a small dead-end room behind a corridor: a pocket under 10% of the floor.</summary>
    public const string Pocket = Loop + """

        local p = kit.room{name = 'p', pos = {-30, 0, 4}, size = {8, 4, 8}}
        kit.corridor{a = p, b = a, width = 4, height = 4}
        """;

    /// <summary>A 30 m deck 3 m wide, 8 m above the floor of a tall hall, reached by stairs: a bridge piece with drops on both sides.</summary>
    public const string Bridge = """
        local h = kit.room{name = 'h', pos = {0, 0, 0}, size = {44, 16, 20}}
        kit.platform{name = 'deck', pos = {0, 0, 0}, size = {30, 3}, height = 8, thickness = 0.5}
        level.place{kind = 'respawn', pos = {-10, 8.5, 0}}
        level.place{kind = 'respawn', pos = {10, 8.5, 0}}
        level.place{kind = 'respawn', pos = {0, 8.5, 0}}
        """;

    /// <summary>A 32 m hall with nine free-standing 1.5 m blocks: cover everywhere near them.</summary>
    public const string Cover = """
        local h = kit.room{name = 'h', pos = {0, 0, 0}, size = {32, 6, 32}}
        for i = -1, 1 do for j = -1, 1 do
          kit.platform{name = 'block' .. i .. j, pos = {i * 9, 0, j * 9}, size = {1.5, 1.5}, height = 1.6}
        end end
        """;

    /// <summary>The same hall with nothing in it (no cover away from the walls).</summary>
    public const string Empty = """
        local h = kit.room{name = 'h', pos = {0, 0, 0}, size = {32, 6, 32}}
        """;

    /// <summary>
    /// Floating platforms: three 14 m decks 30 m up in a 70 m-tall hall, joined by 3 m bridges, with the hall floor far
    /// below out of play — open air above and falls off every edge.
    /// </summary>
    public const string OpenAir = """
        local h = kit.room{name = 'sky', pos = {0, 0, 0}, size = {90, 70, 40}}
        kit.platform{name = 'p1', pos = {-30, 0, 0}, size = {14, 14}, height = 30, thickness = 1}
        kit.platform{name = 'p2', pos = {0, 0, 0}, size = {14, 14}, height = 30, thickness = 1}
        kit.platform{name = 'p3', pos = {30, 0, 0}, size = {14, 14}, height = 30, thickness = 1}
        kit.platform{name = 'b12', pos = {-15, 0, 0}, size = {16, 3}, height = 30, thickness = 1}
        kit.platform{name = 'b23', pos = {15, 0, 0}, size = {16, 3}, height = 30, thickness = 1}
        for _, x in ipairs({-32, -28, -2, 2, 28, 32}) do
          level.place{kind = 'respawn', pos = {x, 30.5, 3}}
        end
        level.player_start{ pos = {0, 31, -3}, yaw = 0 }
        """;

    /// <summary>
    /// A payload chain: a long yard with a One Way cart on a 4-keyframe track, a Payload_Handler linking it, and
    /// checkpoints on keyframes 2 and 3, each switching on 2 red and 2 blue respawn points.
    /// </summary>
    public const string Payload = """
        local yard = kit.room{name = 'yard', pos = {0, 0, 0}, size = {120, 8, 24}}
        level.props:set("multiplayer", true)
        level.alpine:set_many{ legacy_movers = false }
        local route = { {-50, 0.5, 0}, {-15, 0.5, 0}, {20, 0.5, 0}, {50, 0.5, 0} }
        local body = level.brush{ pos = route[1], size = {2, 1, 3}, detail = true }
        local cart = level.create_mover{ name = "cart", brushes = { body }, props = { movement_type = "One Way" } }
        for i = 2, #route do
          cart:add_keyframe{ pos = route[i], props = { travel_time_to_next = 8, return_travel = 8 } }
        end
        level.place{ kind = "event", class = "Payload_Handler", name = "payload", pos = {-50, 2, 0}, links = { cart } }
        for n, k in ipairs({ 2, 3 }) do
          local kf = cart.keyframes[k]
          local cp = level.place{ kind = "event", class = "Payload_Checkpoint", pos = { kf.pos.x, 2, kf.pos.z } }
          kf:set("triggered_event_uid", cp.uid)
          local spawns = {}
          for j = 1, 4 do
            local red = j <= 2
            spawns[j] = level.place{ kind = "respawn", pos = { kf.pos.x + (red and -8 or 8), 0, j * 4 - 10 },
                                     props = { red_team = red, blue_team = not red } }
          end
          cp:link_many(spawns)
        end
        for _, x in ipairs({-55, -45}) do level.place{ kind = "respawn", pos = {x, 0, 6}, props = { red_team = false, blue_team = true } } end
        """;

    /// <summary>
