    public const string SetPieces = """
        local h = kit.room{name = 'hall', pos = {0, 0, 0}, size = {48, 24, 24}}
        kit.platform{name = 'west', pos = {-19, 0, 0}, size = {10, 24}, height = 8}
        kit.platform{name = 'east', pos = {19, 0, 0}, size = {10, 24}, height = 8}
        kit.bridge{name = 'span', from = {-16, 8.125, 0}, to = {16, 8.125, 0}, width = 4, style = 'truss'}
        kit.landmark{name = 'tower', pos = {-6, 0, 7}, height = 15, base = 4}
        kit.platform{name = 'island', pos = {6, 0, 7}, size = {12, 3}, height = 5}
        kit.platform{name = 'ledge', pos = {0, 0, -10.5}, size = {20, 3}, height = 4}
        for _, p in ipairs({ {-19, 8, -6}, {19, 8, 6}, {0, 0, -5}, {10, 0, -2}, {6, 5, 7}, {0, 4, -10.5} }) do
          level.place{kind = 'respawn', pos = p}
        end
        """;

    /// <summary>
    /// Standable floor: a 32 m hall with spawns, a 5 m stack whose top the walk graph reaches only by dropping off it, a
    /// 1.2 m crate stepped onto from the floor, a 0.3 m wall-trim band 1.2 m up the south wall, and a 6 m shelf under a
    /// 1.4 m-high soffit (crouch headroom: floor, but no standing eye point).
    /// </summary>
    public const string Standable = """
        local h = kit.room{name = 'h', pos = {0, 0, 0}, size = {32, 10, 32}}
        kit.platform{name = 'stack', pos = {8, 0, 8}, size = {6, 6}, height = 5}
        kit.platform{name = 'crate', pos = {-8, 0, 8}, size = {2, 2}, height = 1.2}
        kit.platform{name = 'trim', pos = {0, 0, -15.85}, size = {20, 0.3}, height = 1.2}
        kit.platform{name = 'shelf', pos = {-13, 0, -8}, size = {6, 6}, height = 1.0}
        level.brush{pos = {-13, 4.4, -8}, size = {6, 4.0, 6}}
        """;

    /// <summary>
    /// A canyon crossing: 12 m ledges 32 m apart, an 8 m road bridge (truss) with two 0.1 m rails along its deck, and a 3 m
    /// footbridge that runs on, coplanar, into walled approach corridors on both ledges.
    /// </summary>
    public const string CartBridge = """
        local h = kit.room{name = 'canyon', pos = {0, 0, 0}, size = {64, 24, 40}}
        kit.platform{name = 'west', pos = {-24, 0, 0}, size = {16, 40}, height = 12}
        kit.platform{name = 'east', pos = {24, 0, 0}, size = {16, 40}, height = 12}
        kit.bridge{name = 'road', from = {-16, 12.125, -8}, to = {16, 12.125, -8}, width = 8, style = 'truss', landmark = false}
        level.brush{pos = {0, 12.175, -8.55}, size = {32, 0.1, 0.1}, detail = true}
        level.brush{pos = {0, 12.175, -7.45}, size = {32, 0.1, 0.1}, detail = true}
        kit.bridge{name = 'foot', from = {-30, 12.125, 10}, to = {30, 12.125, 10}, width = 3, style = 'plank', landmark = false, purpose = 'report'}
        for _, x in ipairs({-23.25, 23.25}) do
          for _, z in ipairs({7, 13}) do kit.platform{name = 'wall' .. x .. z, pos = {x, 0, z}, size = {13.5, 1}, height = 16} end
        end
        for _, p in ipairs({ {-28, 12, -6}, {28, 12, -6}, {-20, 12, -12}, {20, 12, -12}, {-28, 12.125, 10}, {28, 12.125, 10} }) do
          level.place{kind = 'respawn', pos = p}
        end
        """;

    /// <summary>The payload chain plus a dead-end room off the first segment's yard (a pocket of that segment; its corridor runs inside one column of 8 m cells).</summary>
    public const string PayloadPocket = Payload + """

        local nook = kit.room{name = 'nook', pos = {-36, 0, 26}, size = {6, 4, 6}}
        kit.corridor{a = nook, b = yard, width = 3, height = 4}
        """;

    /// <summary>A 60 m kit.canyon gorge open to the sky through show_sky tops (no ceiling missing: the level stays sealed).</summary>
    public const string Canyon = """
        kit.canyon{name = 'gorge', path = { {0, 0, -30}, {0, 0, 30} }, width = 16, height = 16}
        for _, z in ipairs({ -20, -5, 10, 25 }) do level.place{kind = 'respawn', pos = {0, 0, z}} end
        """;

    /// <summary>
