    /// <summary>
    /// Two rooms on floors 1 m apart joined only by a corridor whose two halves meet in a 1 m step: a route ledge (the
    /// route between the rooms makes players hop).
    /// </summary>
    public const string Ledge = """
        local a = kit.room{name = 'a', pos = {0, 0, 0}, size = {16, 6, 16}}
        local b = kit.room{name = 'b', pos = {33, 1, 0}, size = {16, 6, 16}}
        kit.corridor{name = 'low', width = 3, path = { {8, 0, 0}, {20, 0, 0} }}
        kit.corridor{name = 'high', width = 3, path = { {20, 1, 0}, {25, 1, 0} }}
        for _, p in ipairs({ {-4, 0, -4}, {4, 0, 4}, {29, 1, -4}, {37, 1, 4} }) do level.place{kind = 'respawn', pos = p} end
        """;

    /// <summary>The fixture's kit script plus spawns in each named room (fixtures without explicit spawns).</summary>
    private static string Script(string name) => name switch
    {
        "loop" => Loop + "\n" + Populate("a", 2) + Populate("c", 2),
        "choke" => Choke + "\n" + Populate("a", 3) + Populate("b", 3),
        "pocket" => Pocket + "\n" + Populate("a", 2) + Populate("c", 2),
        "bridge" => Bridge,
        "setpieces" => SetPieces,
        "cover" => Cover + "\n" + Populate("h", 3),
        "empty" => Empty + "\n" + Populate("h", 3),
        "open_air" => OpenAir,
        "payload" => Payload,
        "payload_pocket" => PayloadPocket,
        "standable" => Standable + "\n" + Populate("h", 3),
        "standable_cover" => Standable + "\n" + Populate("h", 3) + "kit.platform{name = 'block', pos = {12, 0, -10}, size = {1.5, 1.5}, height = 1.6}\n",
        "cartbridge" => CartBridge,
        "canyon" => Canyon,
        "flights" => Flights,
        "pit_bridge" => PitBridge,
        "ledge" => Ledge,
        _ => throw new ArgumentException(name),
    };

    /// <summary>The fixture's document and its level (sealed Shared BSP build applied).</summary>
    public static (EditorDocument Doc, SpatialLevel Level) Get(string name) => Built.GetOrAdd(name, n =>
    {
        KitTestHarness.KitRun run = KitTestHarness.Run(Script(n));
        CompiledLevel compiled = KitTestHarness.Sealed(run.Doc, sharedBsp: true);
        GeometryBuildService.Apply(run.Doc.Rfl, compiled);
        return (run.Doc, SpatialLevel.FromDocument(run.Doc, null, GeometryFreshness.StoredFile, n + ".rfl"));
    });

    /// <summary>The fixture measured with the default options (movement links on).</summary>
    public static SpatialAnalysis Analyze(string name, SpatialOptions? options = null) =>
        SpatialAnalysis.Run(Get(name).Level, options ?? new SpatialOptions());
}
